// Pega os binários do webhook e normaliza mimeType: navegador e curl mandam
// octet-stream, e o nó de descompactação ignora o que não está marcado como zip.
const src = $('Webhook Upload CRM').first();
const bin = src.binary || {};
const out = [];
for (const k of Object.keys(bin)) {
  const meta = Object.assign({}, bin[k]);
  const name = (meta.fileName || k || '');
  const lower = name.toLowerCase();
  let kind = null;
  if (lower.endsWith('.xml')) { kind = 'xml'; meta.mimeType = 'application/xml'; meta.fileExtension = 'xml'; }
  else if (lower.endsWith('.zip')) { kind = 'zip'; meta.mimeType = 'application/zip'; meta.fileExtension = 'zip'; }
  else continue;
  out.push({ json: { kind: kind, entry_path: name }, binary: { data: meta } });
}
if (out.length === 0) return [{ json: { kind: 'invalido' } }];
return out;

const input = $input.all();
const out = [];
for (const item of input) {
  const bin = item.binary || {};
  for (const k of Object.keys(bin)) {
    const meta = bin[k];
    const name = (meta.fileName || k || '');
    const lower = name.toLowerCase();
    if (lower.includes('__macosx')) continue;
    if (lower.endsWith('/')) continue;
    let kind = null;
    if (lower.endsWith('.xml')) kind = 'xml';
    else if (lower.endsWith('.zip')) kind = 'zip';
    else continue;
    out.push({ json: { kind: kind, entry_path: name }, binary: { data: meta } });
  }
}
return out;

