const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json;
  const root = j.nfeProc || j.NFe || j;
  const nfe = root.NFe || root;
  const inf = nfe.infNFe || nfe;
  const ide = inf.ide || {};
  const dest = inf.dest || {};
  const ender = dest.enderDest || {};
  const total = (inf.total && inf.total.ICMSTot) || {};
  const detRaw = inf.det || [];
  const det = Array.isArray(detRaw) ? detRaw : [detRaw];
  const chaveRaw = inf.Id || (inf.$ && inf.$.Id) || '';
  const chave = String(chaveRaw).replace(/^NFe/, '');
  const itensOut = det.map(function (d) {
    const p = d.prod || {};
    return {
      external_item_id: String(p.cProd || ''), sku: p.cProd || '',
      product_name: p.xProd || '', quantity: Number(p.qCom || 0),
      unit_price: Number(p.vUnCom || 0), total_price: Number(p.vProd || 0),
      order_ref: p.xPed || '', order_item_ref: p.nItemPed || ''
    };
  });
  out.push({ json: {
    chave_acesso: chave, numero_nf: ide.nNF || '',
    data_emissao: ide.dhEmi || ide.dEmi || '',
    buyer_name: dest.xNome || '', buyer_cpf: dest.CPF || '', buyer_cnpj: dest.CNPJ || '',
    buyer_email: dest.email || '', buyer_phone: dest.fone || '',
    address: { logradouro: ender.xLgr || '', numero: ender.nro || '', bairro: ender.xBairro || '',
               cidade: ender.xMun || '', uf: ender.UF || '', cep: ender.CEP || '' },
    valor_total_nf: Number(total.vNF || 0),
    order_ref_provavel: (itensOut[0] && itensOut[0].order_ref) || '',
    itens: itensOut, raw_nfe: inf
  } });
}
return out;

const MP_BY_CNPJ = { '35635824000112': 'shopee', '03361252000134': 'mercado_livre' };
function digits(s){ return String(s == null ? '' : s).replace(/[^0-9]/g, ''); }
const RUN = $now.toISO();
let CID = '677c58eb-b3ec-493a-ad14-0d052d7d8a45';
try { CID = ($('Webhook Upload CRM').first().json.body || {}).client_id || CID; } catch (e) {}

return $input.all().map(function (it) {
  const j = it.json;
  const cpf = digits(j.buyer_cpf);
  const addr = j.address || {};
  const nfe = j.raw_nfe || {};
  const inter = nfe.infIntermed || {};
  const emit = nfe.emit || {};
  const handle = String(inter.idCadIntTran || '').trim();
  const mp = MP_BY_CNPJ[digits(inter.CNPJ)] || 'shopee';
  const mpLabel = mp === 'shopee' ? 'Shopee' : (mp === 'mercado_livre' ? 'Mercado Livre' : mp);
  const shopId = handle || ('emit:' + digits(emit.CNPJ));
  const orderRef = String(j.order_ref_provavel || '').trim() || String(j.chave_acesso || '');
  return { json: Object.assign({}, j, {
    _run: RUN, client_id: CID,
    cpf_limpo: cpf.length === 11 ? cpf : '',
    order_ref: orderRef, _city: addr.cidade || null, _uf: addr.uf || null,
    mp: mp, shop_id: shopId, shop_name: mpLabel + ' · ' + shopId,
    ordered_at: j.data_emissao || null,
    total_amount: Number(j.valor_total_nf || 0),
    ship_address: j.address || null
  }) };
});

// Junta as notas em um item só. Daqui para a frente cada gravação é UMA
// requisição com um array, em vez de uma por nota — era isso que fazia a
// importação levar minutos.
const notas = $input.all().map(function (i) { return i.json; });
if (notas.length === 0) return [{ json: { vazio: true, lojas: [], clientes: [], notas: [] } }];

const run = notas[0]._run;
const cid = notas[0].client_id;

const lojas = {};
for (const n of notas) {
  const k = n.mp + '|' + n.shop_id;
  if (!lojas[k]) lojas[k] = { client_id: cid, marketplace: n.mp, name: n.shop_name,
                              external_shop_id: n.shop_id, updated_at: run };
}

// Mesmo CPF em várias notas do lote vira uma linha só: mandar repetido no
// array faz o upsert do PostgREST recusar ("cannot affect row a second time").
const clientes = {};
for (const n of notas) {
  if (!n.cpf_limpo) continue;
  const c = clientes[n.cpf_limpo] || { client_id: cid, cpf: n.cpf_limpo, updated_at: run };
  if (n.buyer_name) c.name = n.buyer_name;
  if (n._city) c.city = n._city;
  if (n._uf) c.state = n._uf;
  if (n.buyer_email) c.email = n.buyer_email;
  if (n.buyer_phone) c.phone = n.buyer_phone;
  clientes[n.cpf_limpo] = c;
}

return [{ json: { vazio: false, run: run, client_id: cid,
  lojas: Object.values(lojas), clientes: Object.values(clientes), notas: notas } }];

// Cruza o que voltou das duas gravações anteriores para montar os pedidos.
const lote = $('Montar lotes').first().json;
if (lote.vazio) return [{ json: { pedidos: [] } }];

const porLoja = {};
for (const i of $('Upsert lojas (lote)').all()) {
  const s = i.json;
  if (s && s.id && s.external_shop_id) porLoja[s.marketplace + '|' + s.external_shop_id] = s.id;
}
const porCpf = {};
for (const i of $input.all()) {
  const c = i.json;
  if (c && c.id && c.cpf) porCpf[c.cpf] = { id: c.id, created_at: c.created_at };
}

// Duas notas com o mesmo xPed na mesma loja colidiriam dentro do próprio
// array, e o PostgREST recusa o lote inteiro com "cannot affect row a second
// time". Aqui a última vence, como aconteceria em chamadas separadas.
const porChave = {};
for (const n of lote.notas) {
  if (!n.cpf_limpo) continue;              // nota sem CPF não vira pedido
  const storeId = porLoja[n.mp + '|' + n.shop_id];
  const cli = porCpf[n.cpf_limpo];
  if (!storeId || !cli) continue;
  porChave[storeId + '|' + n.order_ref] = {
    store_id: storeId, customer_id: cli.id, marketplace: n.mp,
    external_order_id: n.order_ref, status: 'importado_nfe',
    total_amount: n.total_amount, currency: 'BRL',
    buyer_cpf: n.cpf_limpo, buyer_name: n.buyer_name || null,
    buyer_email: n.buyer_email || null, buyer_phone: n.buyer_phone || null,
    ship_address: n.ship_address, ordered_at: n.ordered_at, updated_at: lote.run
  };
}
return [{ json: { pedidos: Object.values(porChave) } }];

const lote = $('Montar lotes').first().json;
const porRef = {};
for (const i of $input.all()) {
  const o = i.json;
  if (o && o.id && o.external_order_id) porRef[o.store_id + '|' + o.external_order_id] = o.id;
}
const porLoja = {};
for (const i of $('Upsert lojas (lote)').all()) {
  const s = i.json;
  if (s && s.id && s.external_shop_id) porLoja[s.marketplace + '|' + s.external_shop_id] = s.id;
}

const itens = [];
const estoque = [];
for (const n of (lote.notas || [])) {
  const storeId = porLoja[n.mp + '|' + n.shop_id];
  const orderId = storeId ? porRef[storeId + '|' + n.order_ref] : null;
  if (orderId) {
    for (const it of (n.itens || [])) {
      itens.push({ order_id: orderId, external_item_id: it.external_item_id || null,
        sku: it.sku || null, product_name: it.product_name || null,
        quantity: it.quantity || 1,
        unit_price: it.unit_price === undefined ? null : it.unit_price,
        total_price: it.total_price === undefined ? null : it.total_price });
    }
  }
  // a chave de acesso é o identificador da nota para o estoque: número de NF
  // se repete entre emitentes diferentes
  estoque.push({ ref: n.chave_acesso || n.numero_nf || '',
                 items: (n.itens || []).map(function (it) { return { sku: it.sku, qty: it.quantity }; }) });
}
return [{ json: { itens: itens, estoque: estoque, client_id: lote.client_id } }];

