let viaWebhook = false;
try { viaWebhook = $('Webhook Upload CRM').isExecuted === true; } catch (e) {}

const lote = $('Montar lotes').first().json;
const notas = (lote.notas || []).map(function (n) {
  return { chave_acesso: n.chave_acesso || '', numero_nf: n.numero_nf || '',
           data_emissao: n.data_emissao || '', buyer_name: n.buyer_name || '',
           buyer_cpf: n.buyer_cpf || '', valor_total_nf: Number(n.valor_total_nf || 0),
           order_ref: n.order_ref || '', itens: (n.itens || []).length };
});

const run = new Date(lote.run || Date.now()).getTime() - 60000;
function contar(no) {
  let novos = 0, antigos = 0;
  try {
    $(no).all().forEach(function (i) {
      const d = i.json;
      if (!d || !d.id || !d.created_at) return;
      if (new Date(d.created_at).getTime() >= run) novos++; else antigos++;
    });
  } catch (e) {}
  return { novos: novos, antigos: antigos };
}
const pedidos = contar('Upsert pedidos (lote)');
const clientes = contar('Upsert clientes (lote)');

const semCpf = (lote.notas || []).filter(function (n) { return !n.cpf_limpo; }).length;
let estoqueBaixado = 0, semProduto = 0;
try {
  const e = $('Baixar estoque (lote)').first().json || {};
  estoqueBaixado = Number(e.deducted || 0);
  if (Array.isArray(e.unknown)) semProduto = e.unknown.length;
} catch (e) {}

const datas = notas.map(function (n) { return n.data_emissao; }).filter(Boolean).sort();

return [{ json: {
  ok: true, via_webhook: viaWebhook, client_id: lote.client_id,
  total_nfes: notas.length, com_cpf: notas.length - semCpf, sem_cpf: semCpf,
  novos_pedidos: pedidos.novos, pedidos_atualizados: pedidos.antigos,
  novos_clientes: clientes.novos,
  nota_de: datas[0] || null, nota_ate: datas[datas.length - 1] || null,
  estoque_baixado: estoqueBaixado, itens_sem_produto: semProduto,
  valor_total: notas.reduce(function (s, n) { return s + n.valor_total_nf; }, 0),
  notas: notas
} }];

